def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    sep_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    ]
    sep_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]

    def parts(n, separators):
        bounds = [-1] + separators + [n]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    row_parts = parts(h, sep_rows)
    col_parts = parts(w, sep_cols)

    occupied = []
    for r0, r1 in row_parts:
        for c0, c1 in col_parts:
            cells = [
                (r - r0, c - c0, grid[r][c])
                for r in range(r0, r1)
                for c in range(c0, c1)
                if grid[r][c] != background
            ]
            if cells:
                occupied.append((len(cells), r0, r1, c0, c1, cells))

    if not occupied:
        return [row[:] for row in grid]

    _, sr0, sr1, sc0, sc1, cells = max(occupied)
    pattern = [[background] * (sc1 - sc0) for _ in range(sr1 - sr0)]
    for dr, dc, value in cells:
        pattern[dr][dc] = value

    out = [row[:] for row in grid]
    for r0, r1 in row_parts:
        for c0, c1 in col_parts:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = pattern[(r - r0) % len(pattern)][(c - c0) % len(pattern[0])]
    return out
